/* By AlzRiss - Usanagi Umi AI
 *
 * WALLPAPER KARTU RICH (Task117).
 *
 * Sumber gambar: https://u.pone.rs/ifcwenwn.jpg (foto menu dari owner).
 * Berkas ini dihasilkan oleh tools/gen-wallpaper.py — jangan disunting tangan.
 *
 * Kenapa data URI: kartu HTML dijalankan WebView WhatsApp yang TIDAK punya
 * jaringan, jadi <img src="https://…"> tidak akan pernah muncul. Gambar
 * disematkan langsung (banner 29 KB + latar 7 KB, total ±37 KB).
 *
 * Dipakai oleh: kartu menu (lib/umi-menu/html.js), kartu ping
 * (lib/umi-menu/ping-card.js), dan kartu menuinfo (lib/umi-menu/menuinfo-card.js).
 */

export const WALLPAPER_SOURCE = 'https://u.pone.rs/ifcwenwn.jpg'

/** Potongan wajah — kepala kartu / banner. */
export const WALLPAPER_BANNER = 'data:image/jpeg;base64,'

/** Versi kecil & lembut — latar seluruh halaman. */
export const WALLPAPER_SOFT = 'data:image/jpeg;base64,'

/** Apakah wallpaper bawaan masih dipakai (bisa dimatikan lewat env). */
export function wallpaperEnabled() {
  const flag = String(process.env.UMI_MENU_WALLPAPER || '').toLowerCase()
  return flag !== 'off' && flag !== '0' && flag !== 'false'
}

/**
 * CSS latar.
 *
 * PELAJARAN TASK117b: versi pertama menaruh gambar sebagai
 * `background-image: linear-gradient(rgba…), url("data:…")` pada <body>.
 * Gradasi itu setengah transparan dan `background` bawaan kartu sudah
 * di-reset, jadi begitu gambarnya tidak tampil (WebView WhatsApp sering
 * membuang `url()` berisi data URI), halaman tampil ABU-ABU — persis keluhan
 * owner. Sekarang:
 *   1. warna dasar SELALU pekat (tidak mungkin abu-abu),
 *   2. gambar ditaruh sebagai <img> di lapisan terpisah (wallpaperLayer()),
 *      bukan `url()` di CSS,
 *   3. kalau gambarnya tetap tidak tampil, yang terlihat tetap gradasi laut.
 */
export function wallpaperCss() {
  return `
html{background:#031a2e}
body{background-color:#031a2e;background-image:linear-gradient(160deg,#031a2e 0%,#0a4f7a 55%,#1e90ff 100%);
background-repeat:no-repeat;background-size:cover;background-attachment:scroll}
.wall-layer{position:fixed;inset:0;z-index:0;overflow:hidden;pointer-events:none;
background-image:url("${WALLPAPER_SOURCE}");background-position:center;background-size:cover;background-repeat:no-repeat}
.wall-layer img{display:block;width:100%;height:100%;object-fit:cover;opacity:.34}
.wrap{position:relative;z-index:1}
`
}

/**
 * Lapisan gambar latar (dipasang tepat setelah <body>).
 * Memakai elemen <img>, bukan background-image, supaya data URI tetap
 * dirender walau WebView menyaring `url()`.
 */
export function wallpaperLayer() {
  if (!wallpaperEnabled() || !WALLPAPER_SOFT) return ''
  return `<div class="wall-layer" aria-hidden="true"><img src="${WALLPAPER_SOFT}" alt=""></div>`
}

/** Kepala kartu bergambar (banner) dengan judul + subjudul. */
export function heroBlock({ title = '', subtitle = '', tagline = '', badge = '', extra = '' } = {}) {
  const gambar = wallpaperEnabled() && WALLPAPER_BANNER
    ? `<img class="wall" src="${WALLPAPER_BANNER}" alt="">`
    : ''
  return `  <section class="glass banner">
    <div class="glow"></div>
    ${gambar}
    ${badge ? `<span class="hero-badge">${badge}</span>` : ''}
    ${extra}
    <div class="cap"><b>${title}</b>${subtitle ? `<span>${subtitle}</span>` : ''}${tagline ? `<span class="tag">${tagline}</span>` : ''}</div>
  </section>`
}

export default {
  WALLPAPER_SOURCE, WALLPAPER_BANNER, WALLPAPER_SOFT,
  wallpaperEnabled, wallpaperCss, wallpaperLayer, heroBlock,
}
